/**
 * Which agent preset a Build press opens its new session under.
 *
 * A press of "Build with Joomla" opened a session that wore the WordPress preset (measured 09/09 on a
 * local lane: the header chip said WordPress under a title that said Joomla), because
 * `startSession()` takes no preset and the workspace default is what a fresh session gets. The
 * preset decides the agent's tools, so a Joomla build under it reads and writes a WordPress site.
 *
 * Tracy's twelve presets are `<role>-<platform>` (`config/mode-matrix.json`, generated by
 * `scripts/gen-presets.ts`). The ROLE is the customer's, kept from the session they pressed in; the
 * PLATFORM is the button's. A session under one of dsh's own presets (`standard`, …) has no Tracy
 * role, and a build is design work, so it becomes the designer.
 */

const ROLES = ['designer', 'developer', 'writer', 'seo-geo']
const PLATFORMS = ['wordpress', 'joomla', 'emdash']

/**
 * @param {string | undefined} current - the preset id of the session the press landed in.
 * @param {string} platform - the platform on the button.
 * @returns {string | null} the preset id for the new session, or null for a platform the matrix has no preset for.
 */
export function presetFor(current, platform) {
  if (!PLATFORMS.includes(platform)) return null
  const have = typeof current === 'string' ? current : ''
  const role = ROLES.find((r) => PLATFORMS.some((p) => have === `${r}-${p}`)) ?? 'designer'
  return `${role}-${platform}`
}
